// TODO: Fix the buggy 'average' function below
// fn average(a: Int, b: Int) -> Int
//   ensures: result >= a && result <= b || result >= b && result <= a;
// The bug: integer division truncates, not rounds
// Fix: use (a + b) / 2 but handle odd sums correctly

fn main() -> Int {
  return average(1, 4);
}

solution:
fn average(a: Int, b: Int) -> Int
  ensures: result * 2 == a + b || result * 2 == a + b + 1 || result * 2 == a + b - 1;
{
  return (a + b) / 2;
}

fn main() -> Int {
  return average(1, 4);
}
